// Validate the reviewer decision under the pinned webhook envelope.
// n8n 2.37.10 Webhook v2 nests the POST body under `body` and exposes the
// request headers under `headers` (verified against the pinned image).
//
// The one-time reviewer proof arrives as a header, is forwarded to the demo
// state service for comparison/consumption, and is NEVER echoed into any
// response, transition, or log line.
const raw = $input.first().json;
const input = raw.body ?? raw;
const errors = [];

const reviewId = typeof input.review_id === 'string' ? input.review_id.trim() : '';
if (!reviewId) errors.push('Missing review_id');

// Exact enum: possession of a review id, urgency, or any other data is never
// a decision. Only the literal strings approve/reject pass.
const decision = typeof input.decision === 'string' ? input.decision.trim() : '';
if (decision !== 'approve' && decision !== 'reject') {
  errors.push('decision must be exactly "approve" or "reject" — no other value can be recorded');
}

const proof = String(raw.headers?.['x-reviewer-proof'] ?? '').trim();
if (!proof) errors.push('Missing one-time reviewer authorization (X-Reviewer-Proof header)');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    review_id: reviewId,
    decision,
    reviewer_proof: proof
  }
}];

// Interpret the demo state service's decision-record response.
// Fail closed: ONLY an explicit status=recorded body with an approved or
// rejected review_state counts as a recorded decision. Every other shape —
// auth refusal, unknown review, conflict, malformed — is a refusal, and the
// refusal's own error text (never the proof) is surfaced to the reviewer.
const body = $input.first().json;
const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
const recorded =
  isObject &&
  body.status === 'recorded' &&
  (body.review_state === 'approved' || body.review_state === 'rejected');

if (!recorded) {
  const refusal = isObject && typeof body.error === 'string'
    ? body.error
    : 'the demo state service refused the decision — nothing was recorded';
  const refusedCode = isObject && typeof body.code === 'number' ? body.code : 400;
  return [{ json: { recorded: false, refused_code: refusedCode, refusal } }];
}

return [{
  json: {
    recorded: true,
    review_id: body.review_id,
    review_state: body.review_state,
    decision: body.decision
  }
}];
